body.script:
 // ============================================================ // [ENI] CloudMoon SVG launcher // Wraps the boot page in a full-screen iframe so you can // host it as a .svg and open it from anywhere. // ============================================================ (function() { const params = new URLSearchParams(window.location.search); params.set('t', Date.now()); // cache-bust
const TARGET = "https://cdn.jsdelivr.net/gh/AdenTan123/cloudmoonunblocked@main/15092026.html";
const url = TARGET + "?" + params.toString();

const frame = document.getElementById('cmFrame');
frame.src = url;
})();
